### Dynamic Query Building with Template Literals in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/olap/read-data.mdx

Utilize `sql.statement` for complete SQL queries and `sql.fragment` for reusable SQL parts like conditions or expressions. This distinction aids tooling support.

```typescript
import { sql } from "@514labs/moose-lib";

// Use sql.statement for complete SQL queries
const status = 'active';
const limit = 10;

const query = sql.statement`
  SELECT id, name, email
  FROM ${UserTable}
  WHERE ${UserTable.columns.status} = ${status}
  LIMIT ${limit}
`;

// Use sql.fragment for partial SQL (conditions, expressions, clauses)
interface FilterParams {
  minAge?: number;
  status?: "active" | "inactive";
  searchText?: string;
}

const buildConditionalQuery = (filters: FilterParams) => {
  let conditions = [];

  if (filters.minAge !== undefined) {
    conditions.push(sql.fragment`age >= ${filters.minAge}`);
  }

  if (filters.status) {
    conditions.push(sql.fragment`status = ${filters.status}`);
  }

  if (filters.searchText) {
    conditions.push(sql.fragment`(name ILIKE ${'%' + filters.searchText + '%'} OR email ILIKE ${'%' + filters.searchText + '%'})`);
  }

  let query = sql.statement`SELECT * FROM ${UserTable}`;

  if (conditions.length > 0) {
    query = query.append(sql.fragment` WHERE ${sql.join(conditions, "AND")}`);
  }

  return query.append(sql.fragment` ORDER BY created_at DESC`);
};
```

