### Build Conditional WHERE Clauses

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/apis/analytics-api.mdx

Construct dynamic SQL queries by conditionally appending fragments based on input parameters.

```typescript
import { Sql } from "@514labs/moose-lib";
import { UserTable } from "./UserTable";

interface FilterParams {
  minAge?: number;
  status?: "active" | "inactive";
  searchText?: string;
}

const buildQuery = ({ minAge, status, searchText }: FilterParams, { sql }) => {
  const conditions: Sql[] = [];

  if (minAge !== undefined) {
    conditions.push(sql.fragment`age >= ${minAge}`);
  }

  if (status) {
    conditions.push(sql.fragment`status = ${status}`);
  }

  if (searchText) {
    conditions.push(sql.fragment`(name ILIKE ${'%' + searchText + '%'} OR email ILIKE ${'%' + searchText + '%'})`);
  }

  // Build the full query with conditional WHERE clause
  let query = sql.statement`SELECT * FROM ${UserTable}`;

  if (conditions.length > 0) {
    // Use sql.join() to combine conditions with AND
    query = query.append(sql.fragment` WHERE ${sql.join(conditions, "AND")}`);
  }

  // Use append() to add ORDER BY clause
  query = query.append(sql.fragment` ORDER BY created_at ${sql.raw("DESC")}`);
  return query;
};
```

