import {
  IngestPipeline,
  MaterializedView,
  Api,
  sql,
  Key
} from "@514labs/moose-lib";

// ========================================
// 1. DATA MODEL & INGESTION PIPELINE
// ========================================

export interface ProductEvent {
  event_id: Key<string>;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: string;
  properties: Record<string, any>;
}

// Complete ingestion pipeline
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  ingestApi: true, // Creates POST /ingest/ProductEvent
  stream: true,    // Creates Redpanda topic
  table: {         // Creates ClickHouse table
    orderByFields: ["event_ts", "event_type", "user_id"]
  }
});

// Access the table for queries
const ProductEventTable = ProductEventPipeline.table;

// ========================================
// 2. MATERIALIZED VIEWS FOR AGGREGATIONS
// ========================================

// Top Products - view/cart/purchase counts and revenue
interface TopProductsRow {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const TopProductsView = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["total_revenue", "purchase_count", "product_id"],
  selectStatement: sql.statement`
    SELECT
      product_id,
      sumIf(1, event_type = 'view') AS view_count,
      sumIf(1, event_type = 'cart') AS cart_count,
      sumIf(1, event_type = 'purchase') AS purchase_count,
      sumIf(toFloat64OrZero(JSONExtractFloat(properties, 'price')), event_type = 'purchase') AS total_revenue
    FROM ProductEvent
    GROUP BY product_id
  `,
  selectTables: [ProductEventTable],
});

// Conversion Funnel - views -> carts -> purchases with unique users
interface ConversionFunnelRow {
  step: string;
  total_events: number;
  unique_users: number;
}

export const ConversionFunnelView = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["step"],
  selectStatement: sql.statement`
    SELECT
      event_type AS step,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ProductEvent
    WHERE event_type IN ('view', 'cart', 'purchase')
    GROUP BY event_type
  `,
  selectTables: [ProductEventTable],
});

// Hourly Activity - event counts per hour per event type
interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
}

export const HourlyActivityView = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ProductEvent
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventTable],
});

// ========================================
// 3. CONSUMPTION APIs
// ========================================

// Top Products API - GET /top-products?limit=10
interface TopProductsInput {
  limit?: number;
}

export const topProductsApi = new Api<TopProductsInput, TopProductsRow[]>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    const limitValue = Number(limit);
    const query = sql.statement`
      SELECT *
      FROM TopProducts
      ORDER BY total_revenue DESC, purchase_count DESC
      LIMIT ${limitValue}
    `;
    const data = await client.query.execute<TopProductsRow>(query);
    return await data.json();
  }
);

// Conversion Funnel API - GET /conversion-funnel
interface ConversionFunnelInput {}

export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelRow[]>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const query = sql.statement`
      SELECT *
      FROM ConversionFunnel
      ORDER BY
        CASE step
          WHEN 'view' THEN 1
          WHEN 'cart' THEN 2
          WHEN 'purchase' THEN 3
          ELSE 4
        END
    `;
    const data = await client.query.execute<ConversionFunnelRow>(query);
    return await data.json();
  }
);

// Hourly Activity API - GET /hourly-activity?hours=24
interface HourlyActivityInput {
  hours?: number;
}

export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow[]>(
  "hourly-activity",
  async ({ hours = 24 }, { client, sql }) => {
    const hoursValue = Number(hours);
    const query = sql.statement`
      SELECT *
      FROM HourlyActivity
      WHERE hour >= now() - INTERVAL ${hoursValue} HOUR
      ORDER BY hour ASC, event_type ASC
    `;
    const data = await client.query.execute<HourlyActivityRow>(query);
    return await data.json();
  }
);

